import sqlite3
import os
import hashlib
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
DATABASE = os.environ.get('DB_PATH', '/data/inventory.db')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def require_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key')
        if not api_key:
            return jsonify({'error': 'Missing API key'}), 401
        # Validate against stored keys
        db = get_db()
        row = db.execute('SELECT id, role FROM api_keys WHERE key_hash = ?',
                        (hashlib.sha256(api_key.encode()).hexdigest(),)).fetchone()
        if not row:
            return jsonify({'error': 'Invalid API key'}), 403
        g.caller_role = row['role']
        g.caller_id = row['id']
        return f(*args, **kwargs)
    return decorated

@app.route('/api/inventory/search', methods=['GET'])
@require_api_key
def search_inventory():
    """Search inventory by various fields.
    Supports: name, category, warehouse_id, min_qty
    """
    category = request.args.get('category', '')
    warehouse_id = request.args.get('warehouse_id', '')
    min_qty = request.args.get('min_qty', '0')
    sort_field = request.args.get('sort', 'name')

    # Build query with parameterized values for known fields
    conditions = []
    params = []

    if category:
        conditions.append('category = ?')
        params.append(category)
    if warehouse_id:
        conditions.append('warehouse_id = ?')
        params.append(warehouse_id)
    if min_qty:
        conditions.append('quantity >= ?')
        params.append(min_qty)

    where_clause = ' AND '.join(conditions) if conditions else '1=1'

    # Sort field validated against allowed columns
    allowed_sorts = ['name', 'category', 'quantity', 'updated_at', 'warehouse_id']
    if sort_field not in allowed_sorts:
        sort_field = 'name'

    query = f"SELECT id, name, category, quantity, warehouse_id, updated_at FROM inventory WHERE {where_clause} ORDER BY {sort_field} LIMIT 100"

    db = get_db()
    results = db.execute(query, params).fetchall()
    return jsonify([dict(row) for row in results])

@app.route('/api/inventory/report', methods=['GET'])
@require_api_key
def inventory_report():
    """Generate inventory report with custom grouping."""
    group_by = request.args.get('group_by', 'category')
    having_min = request.args.get('having_min', '0')
    date_from = request.args.get('date_from', '')

    # Construct aggregation query
    date_filter = ''
    if date_from:
        date_filter = f" AND updated_at >= '{date_from}'"

    query = f"SELECT {group_by}, COUNT(*) as count, SUM(quantity) as total_qty FROM inventory WHERE 1=1{date_filter} GROUP BY {group_by} HAVING count >= {having_min}"

    db = get_db()
    try:
        results = db.execute(query).fetchall()
        return jsonify([dict(row) for row in results])
    except sqlite3.OperationalError as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 400

@app.route('/api/inventory/<int:item_id>', methods=['PUT'])
@require_api_key
def update_inventory(item_id):
    """Update inventory item quantity."""
    if g.caller_role not in ('admin', 'warehouse_manager'):
        return jsonify({'error': 'Insufficient permissions'}), 403

    data = request.get_json()
    if not data or 'quantity' not in data:
        return jsonify({'error': 'quantity required'}), 400

    db = get_db()
    db.execute('UPDATE inventory SET quantity = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?',
              (data['quantity'], item_id))
    db.commit()
    return jsonify({'status': 'updated'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
